css:
.fx-sl{width:min(980px,100%);display:grid;gap:clamp(3em,14svh,8em)}
.fx-sl .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-sl h2{font-size:clamp(2.2em,6.4vw,5em);line-height:1.04;letter-spacing:-.02em}
.fx-sl .lead{font:400 clamp(1.15em,2.4vw,1.6em)/1.45 var(--font-body);max-width:30em}
.fx-sl .cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(1.5em,5vw,4em)}
.fx-sl .cols p{opacity:.8}
.fx-sl blockquote{margin:0;font:italic 500 clamp(1.6em,4.4vw,3em)/1.18 var(--font-heading);border-left:4px solid var(--accent);padding-left:clamp(.8em,3vw,1.6em)}
.fx-sl .hint{font-size:.8em;opacity:.5;letter-spacing:.08em;text-transform:uppercase}
.sl-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.sl-l{display:block;overflow:hidden;padding:.1em 0 .18em;margin:-.1em 0 -.18em}
.sl-i{display:block;transform:translateY(calc((1 - var(--l,1))*108%));opacity:calc(var(--l,1)*1.8);will-change:transform}
@media(max-width:700px){.fx-sl .cols{grid-template-columns:minmax(0,1fr)}}

js:
(function(){
var root=document.querySelector('.fx-sl');if(!root)return;
if(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)return;
var els=[].slice.call(root.querySelectorAll('[data-sl]')),inner=[],raf=0,tm=0;
els.forEach(function(e){e.__t=e.textContent.replace(/\s+/g,' ').trim()});
function split(){inner=[];
 els.forEach(function(e){
  e.textContent='';
  var sr=document.createElement('span');sr.className='sl-sr';sr.textContent=e.__t;e.appendChild(sr);
  var box=document.createElement('span');box.setAttribute('aria-hidden','true');e.appendChild(box);
  var ws=e.__t.split(' '),sp=ws.map(function(w,i){var s=document.createElement('span');s.textContent=w+(i<ws.length-1?' ':'');s.style.display='inline';box.appendChild(s);return s});
  var lines=[],top=null;
  sp.forEach(function(s){var t=s.offsetTop;if(top===null||Math.abs(t-top)>3){lines.push([]);top=t}lines[lines.length-1].push(s.textContent)});
  box.textContent='';
  lines.forEach(function(l){var m=document.createElement('span');m.className='sl-l';var i=document.createElement('span');i.className='sl-i';i.textContent=l.join('').replace(/\s+$/,'');m.appendChild(i);box.appendChild(m);inner.push(i)})});
 upd()}
function cl(v){return v<0?0:v>1?1:v}
function upd(){raf=0;var vh=innerHeight||800;
 inner.forEach(function(i){var r=i.parentNode.getBoundingClientRect(),p=cl((vh*.94-r.top)/(vh*.16)),e=1-Math.pow(1-p,3);i.style.setProperty('--l',e.toFixed(3))})}
function req(){if(!raf)raf=requestAnimationFrame(upd)}
addEventListener('scroll',req,{passive:true});
addEventListener('resize',function(){clearTimeout(tm);tm=setTimeout(split,150)});
split();if(document.fonts&&document.fonts.ready)document.fonts.ready.then(split);
})();
